    "clientIp.v.headerPrivateBody": "{header} の値は {ip} です。このヘッダーを設定しているプロキシを確認するか、{where} で「クライアント IP ヘッダー」を空にしてください。",
    "clientIp.v.allPrivateTitle": "Telepy に届くアドレスがすべて内部アドレスです",
    "clientIp.v.allPrivateBody": "Telepy の前のプロキシは、リクエストを転送する時点ですでにあなたのアドレスを失っています（{ip} はそのプロキシ自身のネットワークのアドレスです）。Telepy の設定では取り戻せないため、プロキシ側を直す必要があります。",
    "clientIp.v.directBody": "このリクエストには X-Forwarded-For を付けたプロキシがありません。{ip} から Telepy に直接届いており、Telepy と同じマシンやネットワークから見ている場合は正常です。インターネットからの訪問者はプロキシを経由するため、外部からもう一度確認してください。",
    "clientIp.v.unknownTitle": "このリクエストの接続元を Telepy は判断できません",
    "clientIp.v.unknownBody": "バックエンドには X-Forwarded-For も接続元アドレスも届いていません。",
    "clientIp.fix.title": "Telepy の前のプロキシを直す方法",
    "clientIp.fix.hostNet": "公開ポート経由で接続を受ける Docker 内のリバースプロキシ（Nginx Proxy Manager など）は、すべての訪問者を Docker ブリッジとして見ることがよくあります。{mode} で動かすか Docker の外で動かすと、本当のアドレスが見えるようになります。",
    "clientIp.fix.ipv6": "訪問者が IPv6 で来るのにコンテナネットワークが IPv4 のみの場合、Docker の userland proxy が接続元を書き換えます。そのネットワークで IPv6 を有効にするか、Docker の daemon.json に {setting} を設定してください。",
    "clientIp.fix.noCdn": "{header} などの CDN ヘッダーが Telepy に届いていないため、このリクエストは Cloudflare などの CDN を経由していません。Cloudflare の DNS レコードが「DNS のみ」（灰色の雲）だと、訪問者はプロキシに直接つながります。その場合 {setting} は設定しないでください。訪問者が自分でそのヘッダーを送れます。",
    "clientIp.fix.after": "そのうえでここでもう一度確認してください。「信頼するプロキシ」が {setting} なら内部プロキシは自動的にスキップされます。数値はバックエンドの前にあるプロキシの段数（Traefik を含む）です（{where}）。",
    "clientIp.fix.outside": "自分のネットワークの外から確認してください（スマートフォンのモバイル回線など）。家の中から自分のグローバルアドレスに接続すると、ルーターの NAT ループバックが接続元をルーター自身の内部アドレスに置き換えることがあります。",
    "clientIp.shortChain": "このリクエストが通過したプロキシは「信頼するプロキシ」（{setting}）より少ないです。構成上それが正常なら {where} で値を下げてください。そうでなければ、この経路で来た訪問者は記録されるアドレスを自分で選べてしまいます。",
    "clientIp.headerAbsent": "「クライアント IP ヘッダー」は {header} ですが、このリクエストには含まれていないため、Telepy は X-Forwarded-For を使いました。",
    "clientIp.probe.button": "架空のアドレスで試す",
    "clientIp.probe.hint": "架空の X-Forwarded-For と X-Real-IP ヘッダーを付けてもう一度確認します。訪問者が記録されるアドレスを自分で選べてはいけません。",
    "clientIp.probe.safe": "安全です：Telepy は架空のアドレスを無視しました。",
    "clientIp.probe.spoofableTitle": "訪問者が記録されるアドレスを自分で選べます",
    "clientIp.probe.realIp": "Telepy は架空の {ip} を記録しました。Telepy の前のプロキシが、訪問者の送った X-Real-IP ヘッダー（nginx の real_ip。Nginx Proxy Manager の既定設定）を信頼し、接続元として転送しています。そのプロキシが自分のプロキシからの X-Real-IP だけを信頼するようにする（{setting}）か、real_ip を無効にしてください。",
    "clientIp.probe.sameCause": "原因は上と同じです。訪問者は全員そのプロキシに内部アドレス（{ip}）として届き、Nginx Proxy Manager は既定で内部アドレスからの X-Real-IP を信頼します。プロキシが本当のアドレスを見られるようになれば、これも解消します。",
    "clientIp.probe.forwardedFor": "Telepy は X-Forwarded-For から架空の {ip} を記録しました。「信頼するプロキシ」（{setting}）が実際に通過したプロキシより多く数えています。{where} で値を下げてください。",
    "clientIp.hopsAuto": "自動: 内部アドレスはすべてプロキシとして数えます（このリクエストでは {n} 段をスキップ）",
    "clientIp.hopsFixed": "固定の段数（Traefik を含む）",
    "clientIp.v.hopsBodyAuto": "自動判定では、前段にある公開アドレスのプロキシが訪問者として扱われました。{where} で「信頼するプロキシ」を {setting}（バックエンドの前にあるプロキシの段数、Traefik を含む）にしてから、もう一度確認してください。",
    "clientIp.probe.autoInternalTitle": "内部ネットワークの訪問者は自分の記録アドレスを選べます",
    "clientIp.probe.autoInternal": "Telepy は架空の {ip} を記録しました。あなたは内部アドレスから閲覧しており、「信頼するプロキシ」が {setting} だと内部アドレスがすべてプロキシとして数えられるため、あなたのアドレスがスキップされました。インターネットからの訪問者にはできませんし、内部ネットワークの人も変えられるのは自分自身の記録だけです。完全に防ぐには {where} で「信頼するプロキシ」をバックエンドの前にあるプロキシの段数にしてください。",
