    // 為什麼 / Why
    "wizard.why.title": "なぜこのステップ？",
    "wizard.why.device": "接続するのはデバイスから Telepy への方向なので、デバイスにグローバル IP も開放ポートも要りません。Telepy はキーを知っているデバイスだけを受け入れます。",
    "wizard.why.devicePoint1": "LAN はもともとデバイスをしっかり隔離しています（外からは届きません）。Telepy はそれを崩しません。ポートは開けず、デバイスが外へ 1 本接続するだけです。",
    "wizard.why.devicePoint2": "このキーで開けるのはこのトンネルだけです。漏れても他のデバイスには届きません。",
    "wizard.why.devicePoint3": "次へ進むと、Telepy がこのデバイス専用のポートを確保します。",
    "wizard.why.accounts": "Telepy は実在する OS アカウントとしてデバイスにログインします。このトンネルを共有した人も全員同じ Telepy のキーで入ってくるため、使えるアカウントを制限するのはこのリストです。",
    "wizard.why.accountsPoint1": "デバイスに実在するアカウントを指定してください。わからなければデバイスで whoami を実行します。",
    "wizard.why.accountsPoint2": "共有相手が使えるのは、あとであなたが割り当てたアカウントだけです。",
    "wizard.why.accountsPoint3": "リストはトンネルのメニューからいつでも変更できます。",
    "wizard.why.authorize": "Web ターミナル、ファイル管理、リモートブラウザは、トンネル経由でデバイス自身の sshd にログインして動きます。sshd が受け入れるのは authorized_keys にあるキーだけです。",
    "wizard.why.authorizePoint1": "Telepy のサービスキーは Web ターミナル、ファイル、リモートブラウザ、AI セッションで使われます。",
    "wizard.why.authorizePoint2": "自分のキーがあればノート PC から ssh できます。「自分のキーをインストール」を選んだ場合は、このステップの後に Telepy が追加します。",
    "wizard.why.authorizePoint3": "コマンドは追記するだけです。既存のキーは残り、再実行しても重複しません。",
    "wizard.why.connect": "デバイスが Telepy に接続し、その接続を維持します。この外向きの接続こそがトンネルなので、NAT やファイアウォールの内側でも使えます。",
    "wizard.why.connectPoint1": "クイックテストは、実行したターミナルを閉じると切れます。",
    "wizard.why.connectPoint2": "AutoSSH、systemd サービス、Docker は自動で再接続します。長く使うならいずれかを選んでください。",
    "wizard.why.connectPoint3": "デバイスが接続するとすぐに緑になります。再読み込みは不要です。",
    "wizard.why.verify": "Telepy がトンネル経由で各アカウントに実際にログインします。Web ターミナルと同じ経路なので、問題があれば今のうちに見つかります。",
    "wizard.why.verifyPoint1": "ログインが拒否される原因は、ほぼ必ずそのアカウントの authorized_keys にキーがないことです。",
