    "siteSettings.terminal_detach_max_secs.description": "ブラウザが切れたとき（ネットワーク切替、スリープ、再読み込み）、Web ターミナルのシェルが同じ人の戻りを待つ最大時間です。各自が設定で自分の時間を選び（既定はすぐ終了）、短いほうが適用されます。トンネルを常にすぐ終了にもできます。0 で機能をオフ。最大 86400。",
    "settings.groupSignin": "サインイン",
    "settings.signinBanner": "サインインページの表示、サインインを維持する期間、各アカウントに必須の第二要素。期間の変更は以後のサインインと更新に適用され、現在のセッションは次の更新まで残り時間を保ちます。",
    "settings.unitLabel": "単位",
    "settings.unitSeconds": "秒",
    "settings.unitMinutes": "分",
    "settings.unitHours": "時間",
    "settings.unitDays": "日",
    "siteSettings.signin_lifetime.label": "サインインを維持する期間",
    "siteSettings.signin_lifetime.description": "アクセスがない状態でサインインを維持する期間。アクセスするたびに延長される（タブを開いていればブラウザーがバックグラウンドで更新する）ので、よく使う人はサインアウトされません。この期間を超えて離れると再サインインが必要です。サインアウトすると即座に終了します。5 分から 365 日。",
    "siteSettings.signin_access_lifetime.label": "アクセストークンの有効期間",
    "siteSettings.signin_access_lifetime.description": "短命のアクセストークンそれぞれの有効期間。期限前にブラウザーがサインインセッションで自動的に更新するため、ユーザーは気づきません。短いほど、漏えいしたトークンが使える時間が短くなります。1 分から 24 時間。",
    "siteSettings.signin_page_style.label": "サインインページ",
    "siteSettings.signin_page_style.description": "/login。全員がサインインするページです。",
    "siteSettings.signin_oauth_style.label": "アプリ接続のサインインページ",
    "siteSettings.signin_oauth_style.description": "/oauth/login。MCP アプリが接続を求め、相手がまだサインインしていないときに表示されます。控えめな表示でもアプリ名と戻り先は残し、要求される権限はサインイン後の同意ページに表示します。",
    "siteSettings.signin_cli_style.label": "CLI のサインインページ",
    "siteSettings.signin_cli_style.description": "同じ /oauth/login で、ターミナルで telepy login を実行し、ブラウザーがまだサインインしていないときに表示されます。控えめな表示でも telepy CLI とサインイン元のコンピューターは残し、要求される権限はサインイン後の同意ページに表示します。",
    "siteSettings.signin_consent_style.description": "/oauth/authorize。サインイン済みの人が MCP アプリや telepy login を許可するページです。どちらの見た目でもアプリ、戻り先、権限、トンネルを表示し、控えめな表示では接続の図と手順を省きます。telepy login がサインイン完了後に表示するページもこの見た目に従います。",
    "siteSettings.signin_consent_style.label": "承認ページ（アプリと CLI）",
    "siteSettings.signin_page_message.label": "控えめなページの文",
