    "about.disclaimer": "免責事項",
    "about.disclaimerDescription": "デバイスを接続したり、何かにアクセスを許可したりする前にお読みください。",
    "about.disclaimerLicence": "ライセンス（AGPL-3.0）",
    "about.disclaimer.asIsTitle": "現状のまま・無保証で提供",
    "about.disclaimer.asIsBody": "Telepy は AGPL-3.0 のもとで提供される自由ソフトウェアで、商品性、特定目的への適合性、権利非侵害を含め、明示・黙示を問わず一切の保証なく「現状のまま」提供されます。法律で認められる範囲で、作者および貢献者は、Telepy の使用または使用不能から生じたいかなる損害（データの消失、サービスの停止、システムへの侵入、金銭的損失を含む）についても責任を負いません（AGPL-3.0 第 15 条・第 16 条）。",
    "about.disclaimer.machinesTitle": "操作しているのは実際のマシンです",
    "about.disclaimer.machinesBody": "ターミナル、ファイルマネージャー、リモートデスクトップ、リモートブラウザ、ツールボックスのスニペット、SSH 転送は、あなたのデバイスとそのネットワーク上のマシンに直接作用します。削除、上書き、シャットダウン、権限やファイアウォールの変更は、多くの場合元に戻せません。実行前にどのマシンのどのアカウントにいるかを確かめ、バックアップはご自身で取ってください。コマンドルール、本人確認（step-up）、録画はミスを減らすためのもので、セキュリティ境界ではなく、すべての危険な操作を止められるわけではありません。",
    "about.disclaimer.authorizedTitle": "利用を許可されたシステムだけに接続する",
    "about.disclaimer.authorizedBody": "接続してよいのは、あなたが所有しているか、明示的にアクセスを許可されたデバイスとネットワークだけです。許可のないシステムに対するネットワークスキャン、踏み台接続、ポート転送は、法律（たとえば不正アクセス行為の禁止等に関する法律）や所属組織の規程に違反するおそれがあります。その責任は利用者にあり、Telepy とその作者は負いません。",
    "about.disclaimer.credentialsTitle": "鍵・トークン・サインインはパスワードと同じ",
    "about.disclaimer.credentialsBody": "SSH 鍵、API トークン（tpt_…）、CLI のサインイン、MCP アプリの接続は、いずれもあなたの権限でデバイスに到達でき、それらが行った操作はあなたの名前で行われたことになります。パスワードと同じように扱ってください。チャット、コードリポジトリ、公開された CI ログには貼らず、それぞれに必要なスコープ・トンネル・有効期限だけを与え、使わなくなったものはすぐに取り消してください。",
    "about.disclaimer.agentsTitle": "MCP エージェントは読んだ内容に従って動く",
    "about.disclaimer.agentsBody": "接続した MCP アプリは、あなたが承認した範囲で、デバイス上でコマンドを実行し、ファイルを読み書きし、ブラウザを操作できます。AI はあなたの意図を誤解したり、誤ったコマンドを生成したり、Web ページ・ファイル・コマンド出力に隠された指示（プロンプトインジェクション）に誘導されて、頼んでいないことを実行したりすることがあります。信頼できるアプリだけを接続し、スコープとトンネルは最小限にし、危険なコマンドには承認ルールを設け、「AI アクティビティ」ページで実行内容を確認してください。エージェントが与えられた権限で行ったことの責任は、あなたにあります。",
    "about.disclaimer.sharingTitle": "共有は鍵を手渡すこと",
    "about.disclaimer.sharingBody": "トンネルを共有したり、ADMIN 権限を与えたり、ログインアカウントを許可したりすると、相手はそのアカウントとしてデバイスを操作できます。信頼できる相手とだけ共有し、できるだけ終了日を設定し、誰がアクセスできるかを定期的に見直してください。",
    "about.disclaimer.operatorsTitle": "この Telepy サーバーを運用している方へ",
    "about.disclaimer.operatorsBody": "Telepy を自分でホストする管理者は、サーバーの安全（SECRET_KEY、TLS、更新、バックアップ）、発行したアカウントと権限、そして適用される個人情報保護法令（たとえば個人情報保護法）の遵守に責任を負います。Telepy は IP アドレス、サインイン履歴、監査ログ、録画が有効なトンネルではターミナル出力を保存します。何が記録され、どのくらい保存されるかを利用者に伝えてください。",
    "about.disclaimer.closing": "Telepy を使うことで、これらのリスクを理解し、ご自身の使い方に責任を持つことに同意したものとみなされます。この注意事項はライセンスを補足するもので、ライセンスの内容を変更するものではありません。",
